actions.script:
const id = originalValue?.wikiSpaceId
if (!id) return
const find = (name, keys) => ec.entity.find(name).condition(keys).disableAuthz()
const space = find('moqui.resource.wiki.WikiSpace',{wikiSpaceId:id}).one()
if (!space) return
const prefix = 'dbresource://WikiSpace/' + id
if (space.rootPageLocation !== prefix + '.md')
    throw new Error('Cannot remove a room space with a different storage root')
const wiki = 'moqui.resource.wiki.'
// each page's rows as delete#WikiPage removes them; a page that fails is logged and the others go on, and
// the space's files go below with all of its pages' files
for (const page of find(wiki+'WikiPage',{wikiSpaceId:id}).forUpdate(true).list()) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('org.moqui.resource.WikiServices.delete#WikiPageRows')
            .parameter('wikiPageId', page.wikiPageId).disableAuthz().call()
        if (ec.message.hasError()) ec.logger.error('Could not remove page ' + page.wikiPageId + ' of room space ' + id + ': ' + ec.message.errorsString)
    } catch (e) { ec.logger.error('Could not remove page ' + page.wikiPageId + ' of room space ' + id + ': ' + e) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
find(wiki+'WikiPageAlias',{wikiSpaceId:id}).deleteAll()
find(wiki+'WikiSpaceUser',{wikiSpaceId:id}).deleteAll()
function remove(ref) {
    if (!ref.exists) return
    if (ref.isDirectory()) for (const child of ref.getDirectoryEntries()) remove(child)
    ref.delete()
}
remove(ec.resource.getLocationReference(prefix))
remove(ec.resource.getLocationReference(space.rootPageLocation))
space.delete()
